package org.jarvisassistant.app;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import androidx.test.platform.app.InstrumentationRegistry;import org.junit.*;import static org.junit.Assert.*;import java.lang.reflect.*;import java.io.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Explicit owned-phone preview. Never accesses the production app's records or cookies. */
public class PetRazrChecks {
 private final Instrumentation runner=InstrumentationRegistry.getInstrumentation();
 private Object field(Object o,String n){try{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}catch(Exception e){throw new AssertionError(e);}}
 private void call(Object o,String n){try{Method m=o.getClass().getDeclaredMethod(n);m.setAccessible(true);m.invoke(o);}catch(Exception e){throw new AssertionError(e);}}
 private void shot(Activity a,String n){try{View v=a.getWindow().getDecorView();Bitmap b=Bitmap.createBitmap(v.getWidth(),v.getHeight(),Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));try(FileOutputStream out=new FileOutputStream(new File(a.getExternalFilesDir(null),n+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}catch(Exception e){throw new AssertionError(e);}}
 @Test public void coverWakeCameraAndCleanup()throws Exception{
  Context c=runner.getTargetContext();assertEquals("org.jarvisassistant.app.design",c.getPackageName());runner.getUiAutomation().grantRuntimePermission(c.getPackageName(),android.Manifest.permission.RECORD_AUDIO);runner.getUiAutomation().grantRuntimePermission(c.getPackageName(),android.Manifest.permission.CAMERA);
  c.getSharedPreferences("PetModeActivity",0).edit().putString("layout","cover").commit();
  Instrumentation.ActivityMonitor monitor=runner.addMonitor(PetModeActivity.class.getName(),null,false);ActivityOptions options=ActivityOptions.makeBasic();options.setLaunchDisplayId(Integer.parseInt(InstrumentationRegistry.getArguments().getString("displayId","0")));
  c.startActivity(new Intent(c,PetModeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("origin","https://fixture.tailtest.ts.net"),options.toBundle());PetModeActivity a=(PetModeActivity)runner.waitForMonitorWithTimeout(monitor,20000);assertNotNull("Pet activity reached requested display",a);
  try{
   Thread.sleep(4500);boolean[] protectedState={false};runner.runOnMainSync(()->{protectedState[0]=(Boolean)field(a,"lowBattery");if(protectedState[0]){assertFalse("Thermal protection pauses recording",((PetTalkSession)field(a,"conversation")).microphoneOn());shot(a,"pet-014-power-saving");}});Assume.assumeFalse("Device thermal or low battery protection prevents live sensor acceptance",protectedState[0]);runner.runOnMainSync(()->{assertTrue("Wake state="+((android.widget.TextView)field(a,"status")).getText()+", visible="+field(a,"visible")+", lowBattery="+field(a,"lowBattery"),((PetTalkSession)field(a,"conversation")).running());assertTrue("Microphone actually records in the pet session",((PetTalkSession)field(a,"conversation")).microphoneOn());assertFalse(((PetTalkSession)field(a,"conversation")).ownerMode());assertNotNull(field(a,"camera"));assertEquals(View.GONE,((View)field(a,"deck")).getVisibility());assertEquals(View.VISIBLE,((View)field(a,"reveal")).getVisibility());assertTrue((a.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)!=0);shot(a,"pet-013-cover");((PetFaceView)field(a,"face")).react(PetReactions.Cue.WAVE);});
   Thread.sleep(300);runner.runOnMainSync(()->shot(a,"pet-013-wave"));runner.runOnMainSync(()->call(a,"toggleTalk"));Thread.sleep(800);runner.runOnMainSync(()->{PetTalkSession voice=(PetTalkSession)field(a,"conversation");assertTrue("Talk starts recording immediately",voice.microphoneOn());assertFalse("Talk does not wait for a wake phrase",voice.waitingForWake());assertEquals(View.VISIBLE,((View)field(a,"coverCaption")).getVisibility());assertEquals(.55f,a.getWindow().getAttributes().screenBrightness,.001f);shot(a,"pet-013-talk");call(a,"pauseListening");});boolean[] open={false};long deadline=SystemClock.elapsedRealtime()+15000;while(!open[0]&&SystemClock.elapsedRealtime()<deadline){Thread.sleep(200);runner.runOnMainSync(()->open[0]=(Boolean)field(a,"cameraOpen"));}assertTrue("Actual Razr camera opened for granted local tracking",open[0]);runner.runOnMainSync(()->{assertFalse((Boolean)field(a,"front"));assertFalse(((PetTalkSession)field(a,"conversation")).running());shot(a,"pet-013-camera");});
   runner.runOnMainSync(()->call(a,"controls"));Thread.sleep(400);runner.runOnMainSync(()->{Dialog d=(Dialog)field(a,"sheet");assertTrue(d.isShowing());View v=d.getWindow().getDecorView();Bitmap b=Bitmap.createBitmap(v.getWidth(),v.getHeight(),Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));try(FileOutputStream out=new FileOutputStream(new File(a.getExternalFilesDir(null),"pet-013-controls.png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}catch(IOException e){throw new AssertionError(e);}b.recycle();d.dismiss();});
   if("true".equals(InstrumentationRegistry.getArguments().getString("holdPreview"))){Thread.sleep(45000);runner.runOnMainSync(()->shot(a,"pet-013-expanded-cover"));}
   runner.runOnMainSync(()->((PetTalkSession)field(a,"conversation")).ownerMode(true));
  }finally{runner.runOnMainSync(a::finish);runner.removeMonitor(monitor);}
  Thread.sleep(600);assertFalse(((PetTalkSession)field(a,"conversation")).running());assertFalse(((PetTalkSession)field(a,"conversation")).ownerMode());assertNull(field(a,"camera"));
 }
 @Test public void bundledMusicModelRunsLocallyAndRejectsSilence()throws Exception{
  Context c=runner.getTargetContext();assertEquals("org.jarvisassistant.app.design",c.getPackageName());CountDownLatch got=new CountDownLatch(1);AtomicReference<Float> score=new AtomicReference<>();AtomicBoolean failed=new AtomicBoolean();PetMusic music=new PetMusic(c,value->{score.set(value);got.countDown();},()->{failed.set(true);got.countDown();});try{music.accept(new short[16000],16000);assertTrue(got.await(20,TimeUnit.SECONDS));assertFalse("Music model loaded and inferred",failed.get());assertNotNull(score.get());assertTrue("Silence must not trigger dancing",score.get()<.6f);}finally{music.close();}
 }
}
